#include <string>
#include <utility>

struct Widget {};

inline std::string receive(const Widget&) { return "copy"; }
inline std::string receive(Widget&&) { return "move"; }

template <typename T>
std::string relay(T&& widget)
{
    return receive(std::forward<T>(widget));
}
